"""Publish complete C comparisons, including formatting and precision failures."""
import csv
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def main():
    r=json.loads((ROOT/'docs/task_c_check.json').read_text())
    assert r['complete'] and len(r['station_results'])==4 and len(r['sites'])==33
    timings=json.loads((ROOT/'docs/task_c_timings.json').read_text())
    windows=[];links=[]
    for station in r['station_results']:
        assert station['minute_samples']==43824*60+1
        for c in station['comparisons']:windows.append(dict(station=station['station'],**c,exceeds_60s=max(abs(c['rise_diff_s']),abs(c['set_diff_s']))>60))
    for site in r['sites']:
        for sid,v in site['stations'].items():links.append(dict(site=site['id'],station=sid,hours=v['hours'],browser_hours=v['browser_hours'],diff_h=v['diff_h'],bit_mismatches=len(v['mismatched_hour_indices']),exceeds_1h=abs(v['diff_h'])>1))
    for name,rows in [('task_c_windows.csv',windows),('task_c_links.csv',links)]:
        with (ROOT/'docs'/name).open('w',encoding='utf-8',newline='') as f:
            w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
    summary=dict(stations=4,window_count=sum(s['window_count'] for s in r['station_results']),
        minute_samples=sum(s['minute_samples'] for s in r['station_results']),max_edge_diff_s=max(s['max_edge_diff_s'] for s in r['station_results']),
        window_failures=[w for w in windows if w['exceeds_60s']],
        unmatched_windows={s['station']:dict(computed=s['unmatched_computed'],stored=s['unmatched_stored']) for s in r['station_results'] if s['unmatched_computed'] or s['unmatched_stored']},
        station_hour_bit_mismatches=sum(len(s['hourly_mismatches']) for s in r['station_results']),
        site_station_pairs=len(links),link_bit_mismatches=sum(v['bit_mismatches'] for v in links),
        max_link_hours_diff=max(abs(v['diff_h']) for v in links),
        app_totals_mismatches=[s['id'] for s in r['sites'] if not s['totals_equal_app']],
        historical_total_mismatches=[dict(id=s['id'],diff=s['historical_totals_diff']) for s in r['sites'] if any(s['historical_totals_diff'].values())],
        daily_mismatched_dates=len(r['daily']['mismatches']),daily_dates=r['daily']['computed_dates'],daily_rows=r['daily']['computed_rows'],
        invalid_json=[name for name,v in r['json_validity'].items() if not v['valid']],runtime_s=r['runtime_s'],full_recomputation_wall_s=timings['full_recomputation_wall_s'])
    (ROOT/'docs/task_c_summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8')
    lines=['# Task C — full ground-station windows and lunar links','','Jiyong; clarified task on main `64e11f9`. All four stations, the full five-year interval 2026-01-01T00Z to 2031-01-01T00Z, every KDSA daily row, and all 33 catalogue sites × four station series were recomputed. This PR changes verification code/docs only.','','## Result','',f"- Recomputed {summary['minute_samples']:,} one-minute samples and {summary['window_count']:,} observing windows; maximum rise/set difference **{summary['max_edge_diff_s']:.6f} s** (criterion ≤60 s). Unmatched windows: {sum(len(v['computed'])+len(v['stored']) for v in summary['unmatched_windows'].values())}.",f"- Four hourly station series: **{summary['station_hour_bit_mismatches']} differing bits** across 175,296 hours. All 132 site×station series: **{summary['link_bit_mismatches']} differing bits** across 5,784,768 bits; max total difference **{summary['max_link_hours_diff']} h** (criterion ≤1 h).",f"- KDSA: {summary['daily_dates']} dates / {summary['daily_rows']} rows recomputed; **{summary['daily_mismatched_dates']} dates differ** under exact displayed-row comparison.",f"- **{len(summary['invalid_json'])} published files fail strict JSON parsing**: "+', '.join('`'+s+'`' for s in summary['invalid_json'])+'.','',
      'All mismatches are retained below and in the machine-readable report. Passing the geometric window criterion does not imply exact KST-minute formatting or valid JSON.','','## Every station','','| Station | Windows recomputed / stored | Max edge difference (s) | Hourly bit mismatches | Unmatched computed / stored |','|---|---:|---:|---:|---:|']
    for s in r['station_results']:lines.append(f"| {s['station']} | {s['window_count']} / {s['stored_window_count']} | {s['max_edge_diff_s']:.9f} | {len(s['hourly_mismatches'])} | {len(s['unmatched_computed'])} / {len(s['unmatched_stored'])} |")
    lines+=['','All individual window comparisons, including signed rise/set differences and peak-height checks: [task_c_windows.csv](task_c_windows.csv). Every failure above 60 s is in [task_c_summary.json](task_c_summary.json); none are filtered from the full table.','','## KST daily comparison','','An exact row includes start minute, end minute and whole-window maximum elevation. The existing producer formats HH:MM by discarding seconds. Our roots are refined independently to a ≤0.04 s bracket; the producer uses a ≤1 s discrete search. A sub-second shift across an integer-minute boundary can therefore change one printed minute even though both edges pass the 60 s criterion. This is reported as a mismatch, not silently snapped to the published value.','','| KST date | Independently computed rows | Published rows |','|---|---|---|']
    for d in r['daily']['mismatches']:lines.append('| '+d['day']+' | `'+json.dumps(d['computed'])+'` | `'+json.dumps(d['stored'])+'` |')
    if not r['daily']['mismatches']:lines.append('| All dates | Exact match | Exact match |')
    lines+=['','## Strict JSON defect','','Goldstone’s final window ends at the analysis boundary before its internal altitude maximum. Madrid’s first window starts after its internal maximum. The producer writes `NaN` for those unavailable peaks. `JSON.parse`/browser `response.json()` reject these complete files. KDSA and Canberra files parse successfully. Existing KDSA UI and station-bit link calculation read different, valid files; this does not prove those current views fail.','','Suggested integrator fix: encode missing interior peak as `null` (or explicitly define a clipped-window maximum), document that choice, and rerun the format check. No production values are changed here. Exact parse errors are in [task_c_check.json](task_c_check.json).','','## All 33 site totals','','`stations.json` stores station-only Moon visibility, not precomputed site×station bits. We therefore compare against actual `core.earthVisible`, `korea.stationBits` and `diff_data.siteStationLink` in a separate Node reference harness, and also against the existing `docs/korea_links_check.json` totals. This resolves the task wording without inventing a per-site cache.','','| Site | Earth-visible h | KDSA link h | Any-DSN link h | App totals equal | Station bit mismatches |','|---|---:|---:|---:|---|---:|']
    for s in r['sites']:
        t=s['totals'];m=sum(len(v['mismatched_hour_indices']) for v in s['stations'].values())
        lines.append(f"| {s['id']} | {t['earth']} | {t['kdsa']} | {t['dsn']} | {s['totals_equal_app']} | {m} |")
    lines+=['','All 132 per-station totals: [task_c_links.csv](task_c_links.csv). Complete packed computed link bits, mismatched hour indices, all windows, KST rows and input hashes: [task_c_check.json](task_c_check.json).','','## Method, sources and scope','','Coordinates were independently read from [NAIF KDSA01 kernel](https://naif.jpl.nasa.gov/pub/naif/pds/wgc/lessons/event_finding_kplo/kernels/fk/kdsa01.tf) and [DSN 810-005 module 301 Rev P, Table 5, page 16](https://deepspace.jpl.nasa.gov/dsndocs/810-005/301/301P.pdf). Exact downloaded source hashes are in station identities. DSN DMS coordinates were converted directly; KDSA LATLON was parsed from the kernel. Published rounded coordinates agree within 5.1e-9°. As in the app’s generator, Skyfield uses WGS84 station positions and apparent Moon-centre altitude without refraction or local station terrain; this checks that convention, not the effect of changing terrestrial reference frames.','','Independent station search: all one-minute samples, every sign-change bracket refined by our vector bisection to ≤0.04 s, local maxima refined with our ternary search, explicit endpoint clipping. Monthly NPZ checkpoints are guarded by source/code/station/input hashes. The full-minute grid also checks the whole span for missing/extra events. All interior daily peaks are comfortably above 10° at these stations; clipped endpoints are explicitly retained.','','We use Skyfield 1.54, DE440s and builtin timescale/Delta-T, as does the producer. The numerical search, KST splitting and lunar Earth-mask loop are our own code; neither korea_links.py nor verify_korea.py is imported. This is an independent implementation of the search/composition, **not an independent astronomical ephemeris model**. Future Earth-rotation prediction accuracy is outside this software agreement test.','','Hourly lunar link = Earth centre above the fixed production terrain mask AND Moon centre ≥10° at the station. Independent NumPy vectors include 2 m observer height, 0.5° mask interpolation and all 43,824 samples. The actual-JS harness is only the comparison target. No lunar terrain is recomputed in this task. This is geometric availability, not antenna booking, signal strength or a link budget.','','## Reproduction','',f"Full minute-grid recomputation: **{timings['full_recomputation_wall_s']:.2f} s**; final fingerprint-checked checkpoint resume: {r['runtime_s']:.2f} s. Implementation/review time is additional. Four CPU station workers, single-thread numerical libraries, two physical CPU cores reserved. GPU was not needed for the Skyfield library.",'','```powershell','node pipeline/task_c_browser.mjs','python pipeline/task_c_check.py --kernel-dir PATH_TO_NAIF_KERNELS','python pipeline/task_c_report.py','python -m pytest pipeline/tests/test_task_c.py -q','```','','The kernel directory must contain the existing de440s.bsp. Download the two cited coordinate sources unchanged to data/processed/task_c/sources/kdsa01.tf and 301P.pdf. Raw sources and monthly altitude arrays remain ignored. Re-running the checker validates checkpoints and every actual-browser input hash before comparisons; a stale-reference rejection was exercised. The browser harness fingerprints its source modules, every fetched file and all four windows files even when strict parsing fails. Text-file SHA-256 can change with CRLF/LF conversion. SI usage and the verification ledger record this check; existing global verification counts are not inflated.','']
    (ROOT/'docs/task_c_check.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps(summary,indent=2))

if __name__=='__main__':main()
